@pytest.mark.asyncio
async def test_run_partial_headers(plugin):
    """
    Scenario: Target server has some but not all headers.
    Expected: Only missing headers are flagged.
    """
    target = "http://partial.test"
    # Only provide CSP and X-Frame-Options
    headers = {
        "Content-Security-Policy": "default-src 'self'",
        "X-Frame-Options": "DENY"
    }
    
    with aioresponses() as m:
        m.get(target, status=200, headers=headers)
        
        findings = await plugin.run(target)
        
        # Should find 2 missing (HSTS and X-Content-Type-Options)
        assert len(findings) == 2
        titles = [f.title for f in findings]
        assert "Missing Security Header: Strict-Transport-Security" in titles
        assert "Missing Security Header: X-Content-Type-Options" in titles

