@pytest.mark.asyncio
async def test_finding_content_integrity(plugin):
    """
    Scenario: Validate the metadata of a generated Finding.
    Expected: Correct plugin_id, severity, and description mapping.
    """
    target = "http://test.com"
    with aioresponses() as m:
        m.get(target, status=200, headers={})
        
        findings = await plugin.run(target)
        finding = findings[0]
        
        # Extract header name from title to check description
        header_name = finding.title.split(": ")[1]
        expected_desc = plugin.REQUIRED_HEADERS[header_name]
        
        assert finding.plugin_id == plugin.plugin_id
        assert finding.severity == Severity.LOW
        assert finding.description == expected_desc
        assert "not found in response" in finding.evidence